var opponentReportKey=null,opponentMatchContext=null;
function renderOpponentReport(){
 const host=document.getElementById('opposition-report');if(!host||host.hidden||view!=='match'||!state)return;
 const key=[state.seed,state.minute,state.tactic,state.lineup.map(id=>id+':'+state.players[id].energy).join(',')].join('|');if(key===opponentReportKey)return;
 const d=Opposition.read(season);if(!d.valid){host.innerHTML='';return;}opponentReportKey=key;
 const text=matchdayText,n=n=>Math.round(n),plan=typeof TacticsBoard!=='undefined'?TacticsBoard.read(season):null;
 host.innerHTML='<section class="opposition-card"><header><div><span class="eyebrow">OPPOSITION / '+(state.phase==='prep'?'킥오프 전':'경기 중')+'</span><h2>'+text(d.club.name)+'</h2><p>'+text(d.plan.description)+'</p></div><span class="opposition-crest" style="background:'+d.club.color+'">'+text(d.club.code)+'</span></header><div class="opposition-plan"><span>포메이션 <b>'+d.plan.formation.split('').join('–')+'</b></span><span>전술 성향 <b>'+text(d.plan.label)+'</b></span><span>리그 최근 경기 <b>'+text(d.recent.join(' · ')||'기록 없음')+'</b></span></div><div class="opposition-condition"><span>상대 체력 <b>'+n(d.condition.opponent)+'</b></span><span>활동 인원 <b>'+d.activePlayers.ours+' : '+d.activePlayers.opponent+'</b></span><span>우리 활동 선수 <b>'+n(d.condition.ours)+'</b></span><span>체력 주의 <b>'+d.condition.tired+'명</b></span></div><div class="opposition-comparisons">'+d.comparisons.map(r=>'<div><span>'+r.label+'</span><b>'+n(r.ours)+' <i>:</i> '+n(r.opponent)+'</b><small>우리 / 상대</small></div>').join('')+'</div><p class="opposition-advice">'+text(d.advice)+(plan?.valid?' <strong>코치 제안: '+text(plan.recommendation.label)+'</strong>':'')+'</p><div class="opposition-roster-heading"><h3>'+(state.phase==='prep'?'상대 예상 선발':'상대 선발')+' 11명</h3><span>능력 100점 · 체력은 경기 중 감소</span></div><table class="opposition-roster"><thead><tr><th>선수 / 포지션</th><th>주능력</th><th>속도</th><th>지구력</th><th>체력</th></tr></thead><tbody>'+d.lineup.map(p=>'<tr'+(p.dismissed?' class="opposition-dismissed"':'')+'><td><i>'+p.no+'</i><span>'+text(p.name)+'<small>'+p.pos+' · '+p.primaryLabel+'</small></span></td><td>'+p.primary+'</td><td>'+p.speed+'</td><td>'+p.endurance+'</td><td><b>'+n(p.energy)+'</b><small>'+(p.dismissed?'퇴장':p.condition)+'</small></td></tr>').join('')+'</tbody></table><p class="opposition-note">카드는 이 경기 안에서만 적용되며 누적 경고·다음 경기 출전 정지는 아직 적용하지 않습니다. 주능력: 선방·수비·패스·결정력. 전력 비교는 현재 체력을 반영합니다. 위의 빠른 전술로 지시를 바꾸거나 전술 분석에서 비교하세요.</p></section>';
}
